export function Toggle({
  className,
  defaultToggled = false,
  disabled = false,
  readonly = false,
  hideLabel = false,
  id,
  labelA = 'Off',
  labelB = 'On',
  labelText,
  onClick,
  onToggle,
  size = 'md',
  toggled,
  ...other
}) {
  const prefix = usePrefix();
  const [checked, setChecked] = useControllableState({
    value: toggled,
    onChange: onToggle,
    defaultValue: defaultToggled,
  });

  function handleClick(e) {
    if (disabled || readonly) {
      e.preventDefault();
      return;
    }
    setChecked(!checked);

    if (onClick) {
      onClick(e);
    }
  }

  const isSm = size === 'sm';
  const sideLabel = checked ? labelB : labelA;

  const wrapperClasses = classNames(
    `${prefix}--toggle`,
    {
      [`${prefix}--toggle--disabled`]: disabled,
      [`${prefix}--toggle--readonly`]: readonly && !disabled,
    },
    className
  );
